function getPathValue(tree: MessageTree, path: string): string | undefined {
  const value = path.split('.').reduce<MessageValue | undefined>((current, key) => {
    if (!current || typeof current === 'string') return current;
    return current[key];
  }, tree);

  return typeof value === 'string' ? value : undefined;
}

export function translate(
  locale: LocaleCode,
  path: string,
  params?: Record<string, string | number>,
): string {
  const current = getPathValue(messages[locale], path);
  const fallback = getPathValue(messages[DEFAULT_LOCALE], path);
  return replaceParams(current ?? fallback ?? path, params);
}
